import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Ustawienia","description":"","frontmatter":{},"headers":[],"relativePath":"pl/car-wash/settings.md","filePath":"pl/car-wash/settings.md"}'),i={name:"pl/car-wash/settings.md"};function r(n,t,c,s,l,z){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ustawienia" tabindex="-1">Ustawienia <a class="header-anchor" href="#ustawienia" aria-label="Permalink to &quot;Ustawienia&quot;">​</a></h1><p>Każde ustawienie Car Wash edytuje się w <code>/nay</code>, na stronie <strong>Car Wash</strong> (scope <code>nay_car_wash.config</code>). Zmiany są zapisywane w bazie danych i od razu stosowane u wszystkich graczy. <code>config.lua</code> zawiera opcjonalne wartości początkowe: obowiązują, dopóki ustawienie nie zostanie zmienione w <code>/nay</code>, a <strong>Przywróć</strong> wraca do nich.</p><p>Kolumna <strong>W /nay</strong> to nazwa wyświetlana w panelu. Klucz to nazwa używana przez <code>config.lua</code> i <a href="/pl/nay-lib/api">API HTTP</a>.</p><h2 id="ogolne" tabindex="-1">Ogólne <a class="header-anchor" href="#ogolne" aria-label="Permalink to &quot;Ogólne&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Włączone</td><td><code>Enabled</code></td><td>wł. / wył.</td><td>wł.</td><td>Włącza lub wyłącza wszystkie tunele i myjki ciśnieniowe.</td></tr><tr><td>Interakcja pieszo</td><td><code>InteractionMode</code></td><td><code>key</code> lub <code>target</code></td><td><code>key</code></td><td>Sposób uruchamiania myjki ciśnieniowej: podpowiedź klawisza (E) lub oko targetu. Tunele zawsze używają E z pojazdu.</td></tr><tr><td>Konto płatności</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> lub <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Skąd pobierana jest opłata. <code>cash_then_bank</code> korzysta z banku, gdy brakuje gotówki.</td></tr><tr><td>Zniżki dla zawodów</td><td><code>JobDiscounts</code></td><td>lista, do 32</td><td>brak</td><td>Zniżki dla zawodu od określonej rangi, w tunelach i na myjkach ciśnieniowych.</td></tr></tbody></table><p>Wpisy <strong>Zniżki dla zawodów</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Zawód</td><td><code>Job</code></td><td>tekst, od 1 do 32 znaków</td><td>Nazwa zawodu, taka jak w Twoim frameworku.</td></tr><tr><td>Minimalna ranga</td><td><code>MinGrade</code></td><td>liczba od 0 do 100</td><td>Najniższa ranga, która otrzymuje zniżkę.</td></tr><tr><td>Zniżka (%)</td><td><code>Percent</code></td><td>liczba od 1 do 100</td><td>Zniżka w procentach. 100 oznacza mycie za darmo.</td></tr></tbody></table><h2 id="tunele" tabindex="-1">Tunele <a class="header-anchor" href="#tunele" aria-label="Permalink to &quot;Tunele&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Programy mycia</td><td><code>Programs</code></td><td>lista, od 1 do 8</td><td>Express 150 $, Standard 250 $, Premium 400 $</td><td>Programy mycia dostępne w każdym tunelu.</td></tr><tr><td>Tunele</td><td><code>Tunnels</code></td><td>lista, do 32</td><td>Strawberry, Little Seoul</td><td>Tunele. Rozmieszczane <a href="/pl/car-wash/tunnels">edytorem tuneli</a>.</td></tr><tr><td>Maksymalna szerokość pojazdu (m)</td><td><code>MaxVehicleWidth</code></td><td>metry, od 1 do 6</td><td>2,25</td><td>Szersze pojazdy są odrzucane.</td></tr><tr><td>Zablokowane klasy pojazdów</td><td><code>BlockedClasses</code></td><td>lista klas pojazdów</td><td>motocykle, rowery, łodzie, helikoptery, samoloty, pociągi</td><td>Klasy pojazdów odrzucane na wjeździe.</td></tr><tr><td>Odrzucaj czyste pojazdy</td><td><code>RequireDirt</code></td><td>wł. / wył.</td><td>wył.</td><td>Odrzuca pojazdy, które są już czyste.</td></tr><tr><td>Podmieniaj IPL myjni z mapy</td><td><code>ReplaceMapIpls</code></td><td>wł. / wył.</td><td>wł.</td><td>W Strawberry zastępuje domyślną myjnię jej wersją bez szczotek. Wyłącz, jeśli tą myjnią zajmuje się własna mapa lub menedżer mappingu.</td></tr></tbody></table><p>Wpisy <strong>Programy mycia</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Nazwa</td><td><code>Label</code></td><td>tekst, od 1 do 32 znaków</td><td>Nazwa wyświetlana w menu mycia.</td></tr><tr><td>Cena</td><td><code>Price</code></td><td>liczba od 0 do 1000000</td><td>Cena przed zniżkami i procentem ceny tunelu.</td></tr><tr><td>Prędkość (%)</td><td><code>SpeedPercent</code></td><td>liczba od 25 do 300</td><td>Prędkość względem prędkości tunelu.</td></tr><tr><td>Piana</td><td><code>Soap</code></td><td>wł. / wył.</td><td>Uruchamia łuk piany.</td></tr><tr><td>Płukanie</td><td><code>Rinse</code></td><td>wł. / wył.</td><td>Uruchamia łuk płukania.</td></tr><tr><td>Suszenie</td><td><code>Dry</code></td><td>wł. / wył.</td><td>Uruchamia suszarkę.</td></tr><tr><td>Wosk (minuty)</td><td><code>WaxMinutes</code></td><td>liczba od 0 do 1440</td><td>Liczba minut, przez które pojazd pozostaje czysty po myciu. 0 oznacza brak wosku.</td></tr></tbody></table><p>Wpisy <strong>Tunele</strong> łatwiej edytować <a href="/pl/car-wash/tunnels">edytorem tuneli</a>, który wypełnia te pola za Ciebie:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Nazwa</td><td><code>Label</code></td><td>tekst, do 48 znaków</td><td>Tytuł menu mycia, używany też w historii i webhookach. Opcjonalne.</td></tr><tr><td>Otwarty</td><td><code>Enabled</code></td><td>wł. / wył.</td><td>Zamyka jeden tunel bez usuwania go.</td></tr><tr><td>Wjazd</td><td><code>Entry</code></td><td>pozycja i kierunek</td><td>Miejsce, w którym kierowca się zatrzymuje i naciska E.</td></tr><tr><td>Początek linii</td><td><code>Start</code></td><td>pozycja</td><td>Początek linii, po której jedzie pojazd.</td></tr><tr><td>Koniec linii</td><td><code>Finish</code></td><td>pozycja</td><td>Koniec linii.</td></tr><tr><td>Szerokość (m)</td><td><code>Width</code></td><td>metry, od 2 do 10</td><td>Szerokość przejazdu: wyznacza rozmiar łuków, ogranicza szerokość pojazdu (margines 0,5 m) i służy do kontroli zablokowanego przejazdu.</td></tr><tr><td>Prędkość (m/s)</td><td><code>Speed</code></td><td>metry na sekundę, od 0,5 do 8</td><td>Bazowa prędkość przejazdu przez tunel, mnożona przez prędkość programu.</td></tr><tr><td>Cena (%)</td><td><code>PricePercent</code></td><td>liczba od 0 do 1000</td><td>Procent stosowany do ceny każdego programu w tym tunelu. 100 zachowuje ceny.</td></tr><tr><td>Łuk piany</td><td><code>SoapJet</code></td><td>pozycja</td><td>Łuk piany.</td></tr><tr><td>Szczotka górna</td><td><code>HorizontalRoller</code></td><td>pozycja</td><td>Szczotka górna.</td></tr><tr><td>Szczotki boczne</td><td><code>VerticalRoller</code></td><td>pozycja</td><td>Szczotki boczne.</td></tr><tr><td>Łuk płukania</td><td><code>RinseJet</code></td><td>pozycja</td><td>Łuk płukania.</td></tr><tr><td>Suszarka</td><td><code>Dryer</code></td><td>pozycja</td><td>Suszarka parowa. Opcjonalne.</td></tr></tbody></table><p>Wpisy <strong>Zablokowane klasy pojazdów</strong> mają jedno pole, <strong>Klasa</strong> (<code>Class</code>), wybierane według nazwy spośród klas pojazdów GTA.</p><h2 id="myjki-cisnieniowe" tabindex="-1">Myjki ciśnieniowe <a class="header-anchor" href="#myjki-cisnieniowe" aria-label="Permalink to &quot;Myjki ciśnieniowe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Myjki ciśnieniowe</td><td><code>ManualEnabled</code></td><td>wł. / wył.</td><td>wł.</td><td>Włącza lub wyłącza myjki ciśnieniowe.</td></tr><tr><td>Propy myjek</td><td><code>ManualModels</code></td><td>lista, do 16</td><td><code>prop_gas_airunit01</code></td><td>Propy świata, które stają się myjkami ciśnieniowymi, wszędzie tam, gdzie występują na mapie.</td></tr><tr><td>Rozmieszczone myjki</td><td><code>ManualStations</code></td><td>lista, do 64</td><td>brak</td><td>Myjki ciśnieniowe, które rozmieszczasz samodzielnie.</td></tr><tr><td>Cena za poziom brudu</td><td><code>ManualPricePerLevel</code></td><td>liczba od 0 do 100000</td><td>15</td><td>Cena jednego poziomu brudu, przed zniżkami dla zawodów.</td></tr><tr><td>Sekundy na poziom brudu</td><td><code>ManualSecondsPerLevel</code></td><td>sekundy, od 0,2 do 10</td><td>1</td><td>Czas wyczyszczenia jednego poziomu brudu.</td></tr></tbody></table><p>Wpisy <strong>Propy myjek</strong> mają jedno pole, <strong>Nazwa modelu</strong> (<code>Model</code>): nazwę modelu propa (litery, cyfry i podkreślenia).</p><p>Wpisy <strong>Rozmieszczone myjki</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Opis</th></tr></thead><tbody><tr><td>Nazwa</td><td><code>Label</code></td><td>tekst, do 48 znaków</td><td>Nazwa stanowiska, używana w historii i webhookach. Opcjonalne.</td></tr><tr><td>Pozycja</td><td><code>Coords</code></td><td>pozycja i kierunek</td><td>Miejsce, w którym stoi. <strong>Użyj mojej pozycji</strong> wypełnia je na podstawie miejsca, w którym stoisz.</td></tr></tbody></table><p>Więcej na stronie <a href="/pl/car-wash/pressure-washers">Myjki ciśnieniowe</a>.</p><h2 id="blipy" tabindex="-1">Blipy <a class="header-anchor" href="#blipy" aria-label="Permalink to &quot;Blipy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Pokaż blipy</td><td><code>ShowBlips</code></td><td>wł. / wył.</td><td>wł.</td><td>Pokazuje na mapie tunele oraz, gdy myjki ciśnieniowe są włączone, rozmieszczone stanowiska.</td></tr><tr><td>Ikona blipa</td><td><code>BlipSprite</code></td><td>ikona blipa</td><td>100</td><td>Wybierana z wizualnej listy ikon. Dla własnego blipa nadal można wpisać dowolny numer.</td></tr><tr><td>Kolor blipa</td><td><code>BlipColor</code></td><td>kolor blipa</td><td>63</td><td>Wybierany z wizualnej listy kolorów.</td></tr><tr><td>Rozmiar blipa</td><td><code>BlipScale</code></td><td>od 0,2 do 2</td><td>0,8</td><td>Rozmiar blipa.</td></tr></tbody></table>',22)])])}const w=d(i,[["render",r]]);export{p as __pageData,w as default};
